import { getCurrentUser } from './auth.ts';

/**
 * Returns authorization headers containing the active user identifier.
 */
export async function getAuthHeaders(): Promise<Record<string, string>> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
  };

  const user = getCurrentUser();
  if (user) {
    headers['Authorization'] = `Bearer ${user.uid}`;
    headers['x-user-id'] = user.uid;
  } else {
    headers['Authorization'] = 'Bearer guest_user';
    headers['x-user-id'] = 'guest_user';
  }

  return headers;
}

/**
 * Wrapper for fetch that automatically attaches the user authorization header
 * and handles standard JSON error responses.
 */
export async function apiFetch<T = any>(
  endpoint: string,
  options: RequestInit = {}
): Promise<T> {
  const authHeaders = await getAuthHeaders();
  const mergedHeaders = {
    ...authHeaders,
    ...((options.headers as Record<string, string>) || {}),
  };

  const response = await fetch(endpoint, {
    ...options,
    headers: mergedHeaders,
  });

  const data = await response.json().catch(() => null);

  if (!response.ok) {
    const errorMsg = data?.error || data?.message || `Request failed with status ${response.status}`;
    throw new Error(errorMsg);
  }

  return data as T;
}
