'use client';

import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import * as authService from '../lib/auth.ts';
import { AuthUser, ConfirmationResult } from '../lib/auth.ts';
import { getUserProfile, saveUserProfile } from '../lib/db.ts';
import { UserProfile } from '../types/index.ts';

interface AuthContextType {
  user: AuthUser | null;
  profile: UserProfile | null;
  loading: boolean;
  guestUser: boolean;
  signInWithGoogle: () => Promise<void>;
  signInWithEmail: (email: string, pass: string) => Promise<void>;
  signUpWithEmail: (email: string, pass: string, name: string) => Promise<void>;
  sendPhoneCode: (phoneNumber: string, containerId: string) => Promise<ConfirmationResult>;
  verifyPhoneCode: (confirmationResult: ConfirmationResult, verificationCode: string) => Promise<void>;
  signOut: () => Promise<void>;
  sendPasswordReset: (email: string) => Promise<void>;
  updateProfile: (updated: Partial<UserProfile>) => Promise<void>;
  continueAsGuest: () => void;
  showAuthModal: boolean;
  setShowAuthModal: (show: boolean) => void;
  authModalMode: 'signin' | 'signup' | 'reset';
  openAuthModal: (mode?: 'signin' | 'signup' | 'reset') => void;
  isConnected: boolean;
  firebaseConnected?: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [guestUser, setGuestUser] = useState<boolean>(false);
  const [showAuthModal, setShowAuthModal] = useState<boolean>(false);
  const [authModalMode, setAuthModalMode] = useState<'signin' | 'signup' | 'reset'>('signin');
  const [isConnected] = useState<boolean>(true);

  const openAuthModal = (modalMode: 'signin' | 'signup' | 'reset' = 'signin') => {
    setAuthModalMode(modalMode);
    setShowAuthModal(true);
  };

  /**
   * User Authentication Handler
   */
  const handleUserAuthenticated = useCallback(
    async (authUser: AuthUser, providerType: string = 'local') => {
      setUser(authUser);
      setGuestUser(authUser.isAnonymous);
      localStorage.removeItem('mealai_guest_mode');
      localStorage.removeItem('mealai_guest_profile');

      try {
        const existing = await getUserProfile(authUser.uid);

        if (existing) {
          const merged: UserProfile = {
            ...existing,
            id: authUser.uid,
            uid: authUser.uid,
            email: authUser.email || existing.email || '',
            name: existing.name || authUser.displayName || 'Chef',
            displayName: existing.displayName || authUser.displayName || existing.name || 'Chef',
            avatar: existing.avatar || authUser.photoURL || '',
            photoURL: existing.photoURL || authUser.photoURL || existing.avatar || '',
            provider: existing.provider || providerType,
            updatedAt: new Date().toISOString(),
          };
          await saveUserProfile(merged);
          setProfile(merged);
        } else {
          const newProfile: UserProfile = {
            id: authUser.uid,
            uid: authUser.uid,
            name: authUser.displayName || (authUser.email ? authUser.email.split('@')[0] : 'Chef'),
            displayName: authUser.displayName || (authUser.email ? authUser.email.split('@')[0] : 'Chef'),
            email: authUser.email || '',
            phoneNumber: authUser.phoneNumber || undefined,
            avatar: authUser.photoURL || '',
            photoURL: authUser.photoURL || '',
            provider: providerType,
            dietaryPreferences: [],
            allergies: [],
            favoriteCuisines: ['Italian', 'Mexican', 'Asian'],
            skillLevel: 'easy',
            householdSize: 2,
            preferredAppliances: ['Stovetop', 'Oven'],
            calorieGoal: 2000,
            proteinGoal: 90,
            dailyBudget: 25,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
          };
          await saveUserProfile(newProfile);
          setProfile(newProfile);
        }
      } catch (error) {
        console.error('[AuthContext] Error loading/creating user profile:', error);
      }
    },
    []
  );

  // Initialize authentication state from local storage
  useEffect(() => {
    const localUser = authService.getCurrentUser();
    if (localUser) {
      handleUserAuthenticated(localUser, 'password');
      setLoading(false);
      return;
    }

    const isGuest = localStorage.getItem('mealai_guest_mode') === 'true';
    if (isGuest) {
      setGuestUser(true);
      const guest: UserProfile = {
        id: 'guest_user',
        uid: 'guest_user',
        name: 'Guest Chef',
        displayName: 'Guest Chef',
        email: 'guest@mealai.app',
        avatar: '',
        photoURL: '',
        provider: 'guest',
        dietaryPreferences: [],
        allergies: [],
        favoriteCuisines: ['Italian', 'Mediterranean', 'Mexican'],
        skillLevel: 'easy',
        householdSize: 2,
        preferredAppliances: ['Stovetop', 'Oven', 'Air Fryer'],
        calorieGoal: 2000,
        proteinGoal: 90,
        dailyBudget: 25,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      setProfile(guest);
    } else {
      setUser(null);
      setGuestUser(false);
      setProfile(null);
    }
    setLoading(false);
  }, [handleUserAuthenticated]);

  const continueAsGuest = () => {
    setLoading(true);
    setGuestUser(true);
    localStorage.setItem('mealai_guest_mode', 'true');
    const guest: UserProfile = {
      id: 'guest_user',
      uid: 'guest_user',
      name: 'Guest Chef',
      displayName: 'Guest Chef',
      email: 'guest@mealai.app',
      avatar: '',
      photoURL: '',
      provider: 'guest',
      dietaryPreferences: [],
      allergies: [],
      favoriteCuisines: ['Italian', 'Mediterranean', 'Mexican'],
      skillLevel: 'easy',
      householdSize: 2,
      preferredAppliances: ['Stovetop', 'Oven', 'Air Fryer'],
      calorieGoal: 2000,
      proteinGoal: 90,
      dailyBudget: 25,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    setProfile(guest);
    setShowAuthModal(false);
    setLoading(false);
  };

  const signInWithGoogle = async () => {
    const authUser = await authService.signInWithGoogleFlow();
    await handleUserAuthenticated(authUser, 'google');
    setShowAuthModal(false);
  };

  const signInWithEmail = async (email: string, pass: string) => {
    const authUser = await authService.signInWithEmail(email, pass);
    await handleUserAuthenticated(authUser, 'password');
    setShowAuthModal(false);
  };

  const signUpWithEmail = async (email: string, pass: string, name: string) => {
    const authUser = await authService.signUpWithEmail(email, pass, name);
    await handleUserAuthenticated(authUser, 'password');
    setShowAuthModal(false);
  };

  const signOut = async () => {
    try {
      await authService.signOutUser();
      setUser(null);
      setGuestUser(false);
      setProfile(null);
      localStorage.removeItem('mealai_guest_mode');
      localStorage.removeItem('mealai_guest_profile');
    } catch (error: any) {
      console.error('[AuthContext] Sign-out error:', error);
    }
  };

  const sendPasswordReset = async (email: string) => {
    await authService.resetPassword(email);
  };

  const sendPhoneCode = async (phoneNumber: string, containerId: string) => {
    const verifier = authService.setupRecaptchaVerifier(containerId);
    return await authService.sendPhoneCode(phoneNumber, verifier);
  };

  const verifyPhoneCode = async (confirmationResult: ConfirmationResult, code: string) => {
    const authUser = await authService.verifyPhoneCode(confirmationResult, code);
    await handleUserAuthenticated(authUser, 'phone');
    setShowAuthModal(false);
  };

  const updateProfile = async (updated: Partial<UserProfile>) => {
    if (!profile) return;
    const newProfile: UserProfile = {
      ...profile,
      ...updated,
      updatedAt: new Date().toISOString(),
    };
    setProfile(newProfile);

    if (user) {
      await saveUserProfile(newProfile);
    } else if (guestUser) {
      localStorage.setItem('mealai_guest_profile', JSON.stringify(newProfile));
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        profile,
        loading,
        guestUser,
        signInWithGoogle,
        signInWithEmail,
        signUpWithEmail,
        sendPhoneCode,
        verifyPhoneCode,
        signOut,
        sendPasswordReset,
        updateProfile,
        continueAsGuest,
        showAuthModal,
        setShowAuthModal,
        authModalMode,
        openAuthModal,
        isConnected,
        firebaseConnected: isConnected,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
