/**
 * Standalone Local Authentication Service
 * Supports Google sign-in (one-click profile creation), Email/Password sign-up and sign-in,
 * Phone SMS verification, and Anonymous Guest access.
 * Persists accounts and active session in browser localStorage.
 */

export interface AuthUser {
  uid: string;
  email: string | null;
  displayName: string | null;
  photoURL: string | null;
  phoneNumber: string | null;
  isAnonymous: boolean;
  emailVerified?: boolean;
  metadata?: {
    creationTime?: string;
    lastSignInTime?: string;
  };
  providerData: Array<{
    providerId: string;
    uid?: string;
    displayName?: string | null;
    email?: string | null;
    phoneNumber?: string | null;
    photoURL?: string | null;
  }>;
  getIdToken: () => Promise<string>;
}

export type User = AuthUser;

export interface ConfirmationResult {
  verificationId: string;
  confirm: (verificationCode: string) => Promise<{ user: AuthUser }>;
}

const STORAGE_USERS_KEY = 'mealai_auth_users';
const STORAGE_CURRENT_USER_KEY = 'mealai_auth_current_user';

// Listeners for auth state changes
type AuthStateCallback = (user: AuthUser | null) => void;
const authListeners: Set<AuthStateCallback> = new Set();

function notifyAuthListeners(user: AuthUser | null) {
  authListeners.forEach((listener) => {
    try {
      listener(user);
    } catch (e) {
      console.error('[Local Auth] Listener error:', e);
    }
  });
}

function getStoredUsers(): Record<string, { passwordHash: string; user: AuthUser }> {
  if (typeof window === 'undefined') return {};
  try {
    const raw = localStorage.getItem(STORAGE_USERS_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function saveStoredUsers(users: Record<string, { passwordHash: string; user: AuthUser }>): void {
  if (typeof window === 'undefined') return;
  try {
    localStorage.setItem(STORAGE_USERS_KEY, JSON.stringify(users));
  } catch (e) {
    console.error('[Local Auth] Failed to save users:', e);
  }
}

function createAuthUserObject(data: Partial<AuthUser>): AuthUser {
  const uid = data.uid || `user_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
  return {
    uid,
    email: data.email || null,
    displayName: data.displayName || null,
    photoURL: data.photoURL || null,
    phoneNumber: data.phoneNumber || null,
    isAnonymous: !!data.isAnonymous,
    emailVerified: data.emailVerified ?? true,
    metadata: data.metadata || {
      creationTime: new Date().toISOString(),
      lastSignInTime: new Date().toISOString(),
    },
    providerData: data.providerData || [
      {
        providerId: data.isAnonymous ? 'anonymous' : 'password',
        uid,
        email: data.email || null,
        displayName: data.displayName || null,
      },
    ],
    getIdToken: async () => uid,
  };
}

export function getCurrentUser(): AuthUser | null {
  if (typeof window === 'undefined') return null;
  try {
    const raw = localStorage.getItem(STORAGE_CURRENT_USER_KEY);
    if (!raw) return null;
    const data = JSON.parse(raw);
    return createAuthUserObject(data);
  } catch {
    return null;
  }
}

function setCurrentUser(user: AuthUser | null): void {
  if (typeof window === 'undefined') return;
  try {
    if (user) {
      localStorage.setItem(STORAGE_CURRENT_USER_KEY, JSON.stringify(user));
    } else {
      localStorage.removeItem(STORAGE_CURRENT_USER_KEY);
    }
    notifyAuthListeners(user);
  } catch (e) {
    console.error('[Local Auth] Failed to set current user:', e);
  }
}

export function onAuthStateChanged(
  _authOrCallback: any,
  callback?: (user: AuthUser | null) => void
): () => void {
  const cb = typeof _authOrCallback === 'function' ? _authOrCallback : callback;
  if (!cb) return () => {};

  authListeners.add(cb);
  // Trigger initial callback asynchronously
  setTimeout(() => {
    cb(getCurrentUser());
  }, 0);

  return () => {
    authListeners.delete(cb);
  };
}

export const isMobileDevice = (): boolean => {
  if (typeof window === 'undefined' || typeof navigator === 'undefined') return false;
  return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
};

export function getFriendlyAuthErrorMessage(error: any): string {
  if (!error) return 'An error occurred. Please try again.';
  const message = error.message || error.toString();
  return message;
}

