/**
 * Sign in with Email and Password
 */
export async function signInWithEmail(email: string, pass: string): Promise<AuthUser> {
  const cleanEmail = email.trim().toLowerCase();
  const users = getStoredUsers();

  const record = users[cleanEmail];
  if (!record) {
    // If not existing yet, create account seamlessly
    const newUser = createAuthUserObject({
      email: cleanEmail,
      displayName: cleanEmail.split('@')[0],
      isAnonymous: false,
    });
    users[cleanEmail] = { passwordHash: pass, user: newUser };
    saveStoredUsers(users);
    setCurrentUser(newUser);
    return newUser;
  }

  if (record.passwordHash !== pass) {
    throw new Error('Email or password is incorrect. Please try again.');
  }

  const user = createAuthUserObject(record.user);
  setCurrentUser(user);
  return user;
}

/**
 * Register with Email and Password
 */
export async function signUpWithEmail(
  email: string,
  pass: string,
  name: string
): Promise<AuthUser> {
  const cleanEmail = email.trim().toLowerCase();
  const users = getStoredUsers();

  const user = createAuthUserObject({
    email: cleanEmail,
    displayName: name.trim() || cleanEmail.split('@')[0],
    isAnonymous: false,
  });

  users[cleanEmail] = { passwordHash: pass, user };
  saveStoredUsers(users);
  setCurrentUser(user);
  return user;
}

