/**
 * Phone Authentication
 */
export async function sendPhoneCode(
  phoneNumber: string,
  _verifier?: any
): Promise<ConfirmationResult> {
  const cleanPhone = phoneNumber.trim();

  return {
    verificationId: 'mock_verification_' + Date.now(),
    confirm: async (_code: string) => {
      const user = createAuthUserObject({
        uid: 'phone_' + cleanPhone.replace(/\D/g, ''),
        phoneNumber: cleanPhone,
        displayName: `Chef (${cleanPhone.slice(-4)})`,
        isAnonymous: false,
        providerData: [
          {
            providerId: 'phone',
            phoneNumber: cleanPhone,
          },
        ],
      });
      setCurrentUser(user);
      return { user };
    },
  };
}

export async function verifyPhoneCode(
  confirmationResult: ConfirmationResult,
  verificationCode: string
): Promise<AuthUser> {
  const result = await confirmationResult.confirm(verificationCode);
  return result.user;
}

/**
 * Sign in as an anonymous guest user
 */
export async function signInAsGuest(): Promise<AuthUser> {
  const guestUser = createAuthUserObject({
    uid: 'guest_' + Math.random().toString(36).substring(2, 9),
    displayName: 'Guest Chef',
    email: 'guest@mealai.app',
    isAnonymous: true,
  });

  setCurrentUser(guestUser);
  return guestUser;
}
